import{t as e}from"./utils-COoNfFoj.js";var t={slug:`giulia-camargo`,influencerName:`Giulia de Oliveira Camargo`,influencerHandle:`@giuliacamaargo`,influencerAvatarUrl:`${e}/giulia-camargo-avatar.jpeg`,heroDescription:`I’ve spent years believing that the right room changes everything — that one conversation between the right two people can shift a career, reframe an idea, or spark something that wouldn’t have existed otherwise. Sobremesa(tech), my philosophy/AI community, was built on that belief. But I was still building the guest list by scrolling through thousands of LinkedIn connections at midnight, shuffling names in my head, drawing seating charts on actual paper — doing the most human part of my work with no system to support it.`,assetTitle:`Network Atlas`,screenshotUrl:`${e}/connor-gillivan.png`,remixUrl:`https://www.perplexity.ai/computer/a/network-atlas-giulia-E.C4i.JCQzG_C0lrRp5v9Q`,promptTitle:`Try Giulia's prompt`,promptText:`Build a system for the thousands of LinkedIn connections and no real system for understanding who’s in my network. I need a CRM that works the way my brain works — not a spreadsheet, something alive. It should let me see who’s in my world, what they’re into, what industries they’re in, what we have in common. I want to be able to filter it. I’m not looking for something technical, I just want to be able to look at my network like a map instead of a list. I’ve attached the export of my LinkedIn connections. I need to be able to filter by city as these are in-person events, and it also needs to generate a personalized welcome message I can send that is very casual, to send as a LinkedIn DM.`};export{t as default};
